import { mkdir, writeFile, chmod, access, constants, readFile } from 'node:fs/promises';
import { join } from 'node:path';

export type PreCommitVariant = 'native' | 'pre-commit-framework';

export interface InitPreCommitOptions {
  cwd: string;
  variant?: PreCommitVariant;
  force?: boolean;
}

export interface InitPreCommitResult {
  filePath: string;
  existed: boolean;
  variant: PreCommitVariant;
}

const NATIVE_HOOK = `#!/usr/bin/env bash
# Agent Doctor pre-commit hook — blocks commits with critical structural issues.
# Generated by: npx @chiragdarji/agent-doctor --init-pre-commit

set -e

# Collect staged agent instruction files
FILES=$(git diff --cached --name-only --diff-filter=ACMR | \\
  grep -E '(^|/)((CLAUDE|AGENTS|GEMINI)\\.md|\\.cursor/rules/.*\\.mdc|\\.github/copilot-instructions\\.md|\\.(cursorrules|windsurfrules))$' || true)

if [ -z "$FILES" ]; then
  exit 0
fi

echo "🩺  Agent Doctor — checking staged instruction files…"

FAILED=0
for f in $FILES; do
  if npx --yes @chiragdarji/agent-doctor "$f" --structural-only --fail-on critical --format text 2>&1; then
    :
  else
    FAILED=1
  fi
done

if [ "$FAILED" -ne 0 ]; then
  echo ""
  echo "❌  Commit blocked: agent instruction file(s) have critical issues."
  echo "    Run 'npx @chiragdarji/agent-doctor <file> --fix' to auto-fix what you can,"
  echo "    then stage the changes and try again."
  exit 1
fi

echo "✅  All agent instruction files passed structural checks."
`;

const PRE_COMMIT_FRAMEWORK_ENTRY = `# Agent Doctor — https://github.com/chiragdarji/agent-doctor
# Add this to your .pre-commit-config.yaml
repos:
  - repo: local
    hooks:
      - id: agent-doctor
        name: Agent Doctor (structural checks)
        language: node
        entry: npx @chiragdarji/agent-doctor
        args: [--structural-only, --fail-on, critical]
        files: '(CLAUDE|AGENTS|GEMINI)\\.md$|\\.mdc$|copilot-instructions\\.md$'
        pass_filenames: true
`;

/**
 * Generates a pre-commit hook for running agent-doctor on staged instruction files.
 *
 * `native` variant writes `.git/hooks/pre-commit` (chmod +x).
 * `pre-commit-framework` variant writes `.pre-commit-config.yaml` (or appends a comment
 * block when the file already exists).
 */
export async function initPreCommit(
  options: InitPreCommitOptions,
): Promise<InitPreCommitResult> {
  const { cwd, variant = 'native', force = false } = options;

  if (variant === 'native') {
    const hooksDir = join(cwd, '.git', 'hooks');
    const hookPath = join(hooksDir, 'pre-commit');

    let existed = false;
    try {
      await access(hookPath, constants.F_OK);
      existed = true;
    } catch {
      // does not exist — fine
    }

    if (existed && !force) {
      // Read the existing hook; if it already references agent-doctor, report as existed
      const existing = await readFile(hookPath, 'utf8').catch(() => '');
      if (!existing.includes('agent-doctor')) {
        throw new Error(
          `.git/hooks/pre-commit already exists. Use --force to overwrite, or add the agent-doctor check manually.`,
        );
      }
      return { filePath: hookPath, existed: true, variant };
    }

    await mkdir(hooksDir, { recursive: true });
    await writeFile(hookPath, NATIVE_HOOK, 'utf8');
    await chmod(hookPath, 0o755);

    return { filePath: hookPath, existed, variant };
  }

  // pre-commit framework variant
  const configPath = join(cwd, '.pre-commit-config.yaml');

  let existed = false;
  try {
    await access(configPath, constants.F_OK);
    existed = true;
  } catch {
    // does not exist — fine
  }

  if (existed && !force) {
    const existing = await readFile(configPath, 'utf8').catch(() => '');
    if (existing.includes('agent-doctor')) {
      return { filePath: configPath, existed: true, variant };
    }
    throw new Error(
      `.pre-commit-config.yaml already exists. Use --force to overwrite, or add the agent-doctor hook entry manually.`,
    );
  }

  await writeFile(configPath, PRE_COMMIT_FRAMEWORK_ENTRY, 'utf8');
  return { filePath: configPath, existed, variant };
}
